      title: 'Todo app with add, toggle, edit, delete, filters and persistence',
      scenario: 'The most common machine-coding question: "Build a todo app with All / Active / Completed filters. Bonus: edit on double-click, clear completed, persist in localStorage."',
      steps: ['State: todos (array of {id, title, done}), filter, editing id and text', 'Derive visible todos and remaining count – do not store them', 'Write add/toggle/remove/edit with immutable updates and functional setState', 'Persist todos with a lazy initializer + effect', 'Add the filter buttons with aria-pressed and an empty-state message'],
      code: "const { useState, useMemo, useEffect } = React;\n\nconst FILTERS = {\n  all: () => true,\n  active: (t) => !t.done,\n  completed: (t) => t.done,\n};\n\nfunction App() {\n  const [todos, setTodos] = useState(() => {\n    try { return JSON.parse(localStorage.getItem('mc-todos')) ?? []; } catch { return []; }\n  });\n  const [text, setText] = useState('');\n  const [filter, setFilter] = useState('all');\n  const [editingId, setEditingId] = useState(null);\n  const [editText, setEditText] = useState('');\n\n  useEffect(() => {\n    try { localStorage.setItem('mc-todos', JSON.stringify(todos)); } catch {}\n  }, [todos]);\n\n  const visible = useMemo(() => todos.filter(FILTERS[filter]), [todos, filter]);\n  const remaining = todos.filter((t) => !t.done).length;\n\n  function addTodo(e) {\n    e.preventDefault();\n    const title = text.trim();\n    if (!title) return;\n    setTodos((prev) => [...prev, { id: Date.now(), title, done: false }]);\n    setText('');\n  }\n  const toggle = (id) => setTodos((prev) => prev.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));\n  const remove = (id) => setTodos((prev) => prev.filter((t) => t.id !== id));\n  const saveEdit = (id) => {\n    const title = editText.trim();\n    setTodos((prev) => prev.map((t) => (t.id === id && title ? { ...t, title } : t)));\n    setEditingId(null);\n  };\n\n  return (\n    <div style={{ fontFamily: 'sans-serif', maxWidth: 420, padding: 16 }}>\n      <h2>Todos</h2>\n      <form onSubmit={addTodo} style={{ display: 'flex', gap: 8 }}>\n        <input value={text} onChange={(e) => setText(e.target.value)} placeholder=\"What needs to be done?\" aria-label=\"New todo\" style={{ flex: 1 }} />\n        <button type=\"submit\">Add</button>\n      </form>\n      <div style={{ margin: '12px 0', display: 'flex', gap: 6 }}>\n        {Object.keys(FILTERS).map((f) => (\n          <button key={f} onClick={() => setFilter(f)} aria-pressed={filter === f}\n            style={{ fontWeight: filter === f ? 'bold' : 'normal' }}>{f}</button>\n        ))}\n      </div>\n      <ul style={{ listStyle: 'none', padding: 0 }}>\n        {visible.map((t) => (\n          <li key={t.id} style={{ display: 'flex', gap: 8, alignItems: 'center', padding: 4 }}>\n            <input type=\"checkbox\" checked={t.done} onChange={() => toggle(t.id)} aria-label={'Toggle ' + t.title} />\n            {editingId === t.id ? (\n              <input autoFocus value={editText} onChange={(e) => setEditText(e.target.value)}\n                onBlur={() => saveEdit(t.id)} onKeyDown={(e) => e.key === 'Enter' && saveEdit(t.id)} />\n            ) : (\n              <span onDoubleClick={() => { setEditingId(t.id); setEditText(t.title); }}\n                style={{ flex: 1, textDecoration: t.done ? 'line-through' : 'none' }}>{t.title}</span>\n            )}\n            <button onClick={() => remove(t.id)} aria-label={'Delete ' + t.title}>x</button>\n          </li>\n        ))}\n      </ul>\n      {visible.length === 0 && <p>No {filter === 'all' ? '' : filter} todos.</p>}\n      <p>{remaining} item(s) left</p>\n      <button onClick={() => setTodos((prev) => prev.filter((t) => !t.done))}>Clear completed</button>\n    </div>\n  );\n}",
